fn extract_rear_chars(s: &Vec<Vec<char>>) -> Vec<char> {
    // Preallocate the result vector with the same length as `s`.
    let mut result = Vec::with_capacity(s.len());
    // For each inner Vec<char>, take its last element (they are guaranteed non‐empty).
    for inner in s {
        // Safe to unwrap because each inner Vec<char> is non‐empty by assumption.
        let last_char = inner.last().unwrap();
        result.push(*last_char);
    }
    result
}

